-- ---------------------------------------------------------------------------
-- FindIT core schema.
--
-- The migration is written once and rendered for the target database through
-- Flyway placeholders, so the same file works for the local H2 database and
-- for Azure SQL Database:
--
--   ${id_identity}   GENERATED BY DEFAULT AS IDENTITY (H2) / IDENTITY(1,1) (SQL Server)
--   ${boolean_type}  BOOLEAN (H2) / BIT (SQL Server)
--   ${bool_true}     TRUE (H2) / 1 (SQL Server)
--   ${bool_false}    FALSE (H2) / 0 (SQL Server)
--   ${datetime_type} TIMESTAMP (H2) / DATETIME2 (SQL Server)
--
-- All timestamps are stored in UTC.
-- ---------------------------------------------------------------------------

CREATE TABLE categories (
    id          BIGINT ${id_identity} PRIMARY KEY,
    name        VARCHAR(60)  NOT NULL,
    description VARCHAR(255),
    active      ${boolean_type} NOT NULL DEFAULT ${bool_true},
    CONSTRAINT uk_categories_name UNIQUE (name)
);

CREATE TABLE locations (
    id          BIGINT ${id_identity} PRIMARY KEY,
    name        VARCHAR(120) NOT NULL,
    description VARCHAR(255),
    active      ${boolean_type} NOT NULL DEFAULT ${bool_true},
    CONSTRAINT uk_locations_name UNIQUE (name)
);

CREATE TABLE users (
    id             BIGINT ${id_identity} PRIMARY KEY,
    email          VARCHAR(180) NOT NULL,
    display_name   VARCHAR(80)  NOT NULL,
    password_hash  VARCHAR(100) NOT NULL,
    role           VARCHAR(20)  NOT NULL,
    active         ${boolean_type} NOT NULL DEFAULT ${bool_true},
    contact_channel VARCHAR(120),
    created_at     ${datetime_type} NOT NULL,
    updated_at     ${datetime_type} NOT NULL,
    CONSTRAINT uk_users_email UNIQUE (email)
);

CREATE INDEX idx_users_role ON users (role);

CREATE TABLE items (
    id                        BIGINT ${id_identity} PRIMARY KEY,
    type                      VARCHAR(10)   NOT NULL,
    title                     VARCHAR(100)  NOT NULL,
    description               VARCHAR(2000) NOT NULL,
    category_id               BIGINT        NOT NULL,
    location_id               BIGINT        NOT NULL,
    event_date                DATE          NOT NULL,
    status                    VARCHAR(20)   NOT NULL,
    created_by                BIGINT        NOT NULL,
    image_blob_name           VARCHAR(200),
    image_content_type        VARCHAR(100),
    private_verification_detail VARCHAR(1000),
    returned_at               ${datetime_type},
    returned_by               BIGINT,
    closed_at                 ${datetime_type},
    moderation_reason         VARCHAR(500),
    created_at                ${datetime_type} NOT NULL,
    updated_at                ${datetime_type} NOT NULL,
    CONSTRAINT fk_items_category FOREIGN KEY (category_id) REFERENCES categories (id),
    CONSTRAINT fk_items_location FOREIGN KEY (location_id) REFERENCES locations (id),
    CONSTRAINT fk_items_created_by FOREIGN KEY (created_by) REFERENCES users (id),
    CONSTRAINT fk_items_returned_by FOREIGN KEY (returned_by) REFERENCES users (id)
);

CREATE INDEX idx_items_type_status ON items (type, status);
CREATE INDEX idx_items_category ON items (category_id);
CREATE INDEX idx_items_location ON items (location_id);
CREATE INDEX idx_items_event_date ON items (event_date);
CREATE INDEX idx_items_created_by ON items (created_by);
CREATE INDEX idx_items_created_at ON items (created_at);

CREATE TABLE claims (
    id                  BIGINT ${id_identity} PRIMARY KEY,
    item_id             BIGINT        NOT NULL,
    claimant_id         BIGINT        NOT NULL,
    explanation         VARCHAR(2000) NOT NULL,
    verification_answers VARCHAR(1000),
    status              VARCHAR(20)   NOT NULL,
    reviewed_by         BIGINT,
    reviewed_at         ${datetime_type},
    review_reason       VARCHAR(1000),
    withdrawn_at        ${datetime_type},
    created_at          ${datetime_type} NOT NULL,
    updated_at          ${datetime_type} NOT NULL,
    CONSTRAINT fk_claims_item FOREIGN KEY (item_id) REFERENCES items (id),
    CONSTRAINT fk_claims_claimant FOREIGN KEY (claimant_id) REFERENCES users (id),
    CONSTRAINT fk_claims_reviewed_by FOREIGN KEY (reviewed_by) REFERENCES users (id)
);

CREATE INDEX idx_claims_item ON claims (item_id);
CREATE INDEX idx_claims_claimant ON claims (claimant_id);
CREATE INDEX idx_claims_status ON claims (status);

CREATE TABLE audit_logs (
    id          BIGINT ${id_identity} PRIMARY KEY,
    actor_id    BIGINT,
    action      VARCHAR(60) NOT NULL,
    entity_type VARCHAR(40) NOT NULL,
    entity_id   VARCHAR(60),
    created_at  ${datetime_type} NOT NULL,
    metadata    VARCHAR(1000)
);

CREATE INDEX idx_audit_created_at ON audit_logs (created_at);
CREATE INDEX idx_audit_entity ON audit_logs (entity_type, entity_id);
